const items = $input.all().map(i => i.json);
if (!items.length) throw new Error('API sem registros');
if (items.length > 100) throw new Error('Limite demonstrativo: 100 registros');
const usuarios = items.map(u => ({ id: Number(u.id), nome: String(u.name ?? '').slice(0,150), email: String(u.email ?? '').slice(0,254) }));
return [{json:{origem:'JSONPlaceholder (dados ficticios)',registros:usuarios,quantidade:usuarios.length,observacao:'Nao utilize dados reais sem base legal e medidas de protecao'}}];

const etapas = [
  { titulo: "1. TRIAGEM", nos: ["Agente 1 - Triagem"] },
  { titulo: "2. QUALIDADE DOS DADOS", nos: ["Agente 2 - Qualidade"] },
  { titulo: "3. ANÁLISE DOS DADOS", nos: ["Agente 3 - Analise", "Agente 3 - Análise"] },
  { titulo: "4. RELATÓRIO EXECUTIVO", nos: ["Agente 4 - Relatorio", "Agente 4 - Relatório"] },
  { titulo: "5. AUDITORIA FINAL", nos: ["Agente 5 - Auditoria"] }
];

function obterResultado(nomes) {
  for (const nome of nomes) {
    try {
      const item = $(nome).first();
      const texto = item.json.output ?? item.json.saida;
      if (typeof texto === "string" && texto.trim()) {
        return texto.replace(/\\n/g, "\n").trim();
      }
    } catch (erro) {
      // Tenta outra variante do nome.
    }
  }
  throw new Error("Saída de agente não encontrada: " + nomes.join(" / "));
}

const data = new Date().toLocaleString("pt-BR", { timeZone: "America/Sao_Paulo" });
const quantidade = $("Preparar dados para agentes").first().json.quantidade;
const v = $("Validar dados e indicadores").first().json.validacao;
if (v.totalRegistros !== quantidade) throw new Error("Quantidade divergente.");
const secoes = etapas.map(etapa => [
  "=".repeat(55),
  etapa.titulo,
  "=".repeat(55),
  obterResultado(etapa.nos)
].join("\n"));

const relatorio = [
  "RELATÓRIO EMPRESARIAL - SISTEMA MULTIAGENTE",
  "Data: " + data,
  "Fonte: JSONPlaceholder - dados fictícios",
  "Registros processados: " + quantidade,
  "Revisão humana obrigatória antes de uso externo",
  "",
  "=".repeat(55),
  "0. INDICADORES OBJETIVOS (JAVASCRIPT)",
  "=".repeat(55),
  "Registros: " + v.totalRegistros,
  "Campos obrigatorios: " + v.camposObrigatorios.join(", "),
  "Completude: " + v.camposPreenchidos + "/" + v.totalCamposObrigatorios + " (" + v.percentualCompletude + "%)",
  "IDs inteiros positivos: " + v.idsInteirosPositivos + " | Inválidos: " + v.idsInvalidos + " | IDs repetidos: " + v.idsDuplicados,
  "E-mails sintaxe basica: " + v.emailsSintaxeBasica + "/" + v.totalRegistros + " (" + v.percentualEmailsSintaxeBasica + "%)",
  "E-mails ausentes: " + v.emailsAusentes + " | formato invalido: " + v.emailsFormatoInvalido + " | repetidos: " + v.emailsDuplicados,
  "Registros exatamente duplicados: " + v.registrosDuplicadosExatos,
  "Nomes repetidos: " + v.nomesRepetidos + " | dominios distintos: " + v.dominiosDistintos,
  "Criterios: " + JSON.stringify(v.criterios, null, 2),
  "Ressalvas: " + v.ressalvas.join(" | "),
  "",
  ...secoes,
  "",
  "=".repeat(55),
  "FIM DO RELATÓRIO",
  "=".repeat(55)
].join("\n\n");

return [{ json: { relatorio } }];

function validar(dados){
 if(!dados||!Array.isArray(dados.registros))throw Error("A entrada deve conter 'registros' (array).");
 const registros=dados.registros;if(!registros.length||registros.length>1000)throw Error("Limite de amostra: 1 a 1000 registros.");
 const texto=v=>String(v??"").trim(), norm=v=>texto(v).toLowerCase(), pct=(a,b)=>Number((100*a/b).toFixed(2)), formatoEmail=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
 const ids=new Set(),emails=new Set(),nomes=new Set(),combinacoes=new Set(),dominios=new Set();
 let camposPreenchidos=0,idsInteirosPositivos=0,idsInvalidos=0,idsDuplicados=0,emailsSintaxeBasica=0,emailsAusentes=0,emailsFormatoInvalido=0,emailsDuplicados=0,nomesRepetidos=0,registrosDuplicadosExatos=0;
 for(const r of registros){
  const id=r?.id,nome=texto(r?.nome),email=norm(r?.email);
  const idPreenchido=id!==null&&id!==undefined&&texto(id)!==""&&!Number.isNaN(id);
  camposPreenchidos+=Number(idPreenchido)+Number(Boolean(nome))+Number(Boolean(email));
  if(Number.isInteger(id)&&id>0){idsInteirosPositivos++;if(ids.has(id))idsDuplicados++;ids.add(id)}else idsInvalidos++;
  if(!email)emailsAusentes++;else{
   if(formatoEmail.test(email)){emailsSintaxeBasica++;dominios.add(email.split("@")[1])}else emailsFormatoInvalido++;
   if(emails.has(email))emailsDuplicados++;emails.add(email);
  }
  const normalizado=norm(nome);
  if(normalizado){if(nomes.has(normalizado))nomesRepetidos++;nomes.add(normalizado)}
  const chave=JSON.stringify([id,normalizado,email]);
  if(combinacoes.has(chave))registrosDuplicadosExatos++;combinacoes.add(chave);
 }
 const totalRegistros=registros.length,totalCamposObrigatorios=totalRegistros*3;
 return {origemIndicadores:"JavaScript - regras deterministicas",totalRegistros,camposObrigatorios:["id","nome","email"],totalCamposObrigatorios,camposPreenchidos,percentualCompletude:pct(camposPreenchidos,totalCamposObrigatorios),idsInteirosPositivos,idsInvalidos,idsDistintosValidos:ids.size,idsDuplicados,emailsSintaxeBasica,percentualEmailsSintaxeBasica:pct(emailsSintaxeBasica,totalRegistros),emailsAusentes,emailsFormatoInvalido,emailsDuplicados,nomesRepetidos,registrosDuplicadosExatos,dominiosDistintos:dominios.size,criterios:{completude:"Valores presentes nos 3 campos; porcentagem = preenchidos / (registros x 3).",id:"Inteiro positivo; repetição contada apenas entre IDs válidos.",email:"Verificação básica por expressão regular; não verifica se o endereço existe.",duplicidade:"Registro duplicado exato = mesmo id, nome normalizado e email normalizado. Nomes repetidos são indicador separado.",dominios:"Domínios distintos apenas de e-mails com sintaxe básica."},aprovacaoHumanaObrigatoria:true,ressalvas:["Amostra fictícia de demonstração.","Porcentagens não representam resultados de empresa real.","Validação de formato não verifica entregabilidade de e-mail."]};
}

const dados = $input.first().json;
return [{ json: { ...dados, validacao: validar(dados) } }];
